def verify_isbn(isbn: str) -> str:
    # Remove hyphens and validate length
    numeric = isbn.replace('-', '')
    if len(numeric) != 10:
        return "Right"  # or raise an error; assume correct format
    # Compute checksum for first 9 digits
    try:
        digits = [int(c) for c in numeric[:9]]
    except ValueError:
        return "Right"  # invalid digits
    total = sum((i + 1) * d for i, d in enumerate(digits))
    remainder = total % 11
    expected_checksum = 'X' if remainder == 10 else str(remainder)
    actual_checksum = numeric[9]
    if expected_checksum == actual_checksum:
        return "Right"
    # Build corrected ISBN string keeping hyphen positions
    parts = isbn.split('-')
    parts[-1] = expected_checksum
    return '-'.join(parts)

def verify_isbn(isbn: str) -> str:
    # Remove hyphens to get the 10 characters
    digits = [c for c in isbn if c != '-']
    if len(digits) != 10:
        # Invalid format, but we will still attempt to correct
        return isbn

    # Compute weighted sum
    total = 0
    for i, ch in enumerate(digits, start=1):
        if i == 10 and ch.upper() == 'X':
            val = 10
        else:
            val = int(ch)
        total += i * val

    # Check if correct
    if total % 11 == 0:
        return "Right"

    # Compute correct checksum digit
    sum_first9 = sum((i + 1) * int(digits[i]) for i in range(9))
    correct_digit = None
    for d in range(11):
        if (sum_first9 + 10 * d) % 11 == 0:
            correct_digit = d
            break

    # Convert digit to character, use 'X' for 10
    correct_char = 'X' if correct_digit == 10 else str(correct_digit)

    # Rebuild ISBN with corrected last part
    parts = isbn.split('-')
    parts[-1] = correct_char
    return '-'.join(parts)

