def max_happiness(n: int, m: int, items: list[tuple[int, int]]) -> int:
    """
    Solve a 0‑1 knapsack where the value of an item is its price multiplied by its importance.
    """
    # initialise dp array
    dp = [0] * (n + 1)
    for price, importance in items:
        value = price * importance
        if price > n:
            continue
        for w in range(n, price - 1, -1):
            new_val = dp[w - price] + value
            if new_val > dp[w]:
                dp[w] = new_val
    return dp[n]

