def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    k = int(1.5 * m)  # floor of 150% of planned recruits
    # Sort by score descending, then registration number ascending
    sorted_app = sorted(applicants, key=lambda x: (-x[1], x[0]))
    if not sorted_app or k <= 0:
        return (0, [])
    # Determine cutoff score
    cutoff_index = min(k - 1, len(sorted_app) - 1)
    cutoff = sorted_app[cutoff_index][1]
    # All applicants with scores >= cutoff qualify
    qualified = [app for app in sorted_app if app[1] >= cutoff]
    return (cutoff, qualified)

