def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    # Mapping from node value to its position in inorder for O(1) lookups
    inorder_index = {ch: i for i, ch in enumerate(inorder)}

    def helper(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        if in_start > in_end or post_start > post_end:
            return ""
        # Root is always the last element in current postorder segment
        root = postorder[post_end]
        in_root = inorder_index[root]
        # Number of nodes in left subtree
        left_size = in_root - in_start

        left_pre = helper(in_start, in_root - 1, post_start, post_start + left_size - 1)
        right_pre = helper(in_root + 1, in_end, post_start + left_size, post_end - 1)
        return root + left_pre + right_pre

    return helper(0, len(inorder) - 1, 0, len(postorder) - 1)

