def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal
    based on the given statements. The function disregards any statements that
    mention the day of the week.
    """
    # Helper to determine truth value of a single statement.
    def evaluate(stmt: str, speaker: str) -> bool | None:
        # Ignore statements that mention a day of the week
        for day in days_of_week:
            if day in stmt:
                return None
        # Normalise punctuation and case
        s = stmt.strip()
        if s.endswith('.'):
            s = s[:-1]
        s_lower = s.lower()

        # Self statements
        if s_lower == "i am guilty":
            return speaker == scenario
        if s_lower == "i am not guilty":
            return speaker != scenario

        # Statements about other participants
        parts = s.split()
        if len(parts) >= 3 and parts[1].lower() == "is":
            subject = parts[0]
            if len(parts) == 3 and parts[2].lower() == "guilty":
                return subject == scenario
            if len(parts) >= 4 and parts[2].lower() == "not" and parts[3].lower() == "guilty":
                return subject != scenario
        # Unknown format – ignore
        return None

    for speaker, stmts in statements.items():
        is_liar = speaker in liar_count
        for stmt in stmts:
            truth = evaluate(stmt, speaker)
            if truth is None:
                continue  # ignore the statement
            if is_liar and truth:
                return False  # liar told a true statement
            if not is_liar and not truth:
                return False  # truth-teller told a false statement
    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    import re
    for speaker, stmts in statements.items():
