def remaining_trees_after_clearing(l: int, areas: list) -> int:
    """
    Calculate the number of remaining trees along a road after specific
    areas have been cleared.  
    Intervals are considered half‑open [start, end) as inferred from the examples.
    """
    if l <= 0 or not areas:
        return max(0, l)

    # Clamp intervals to the road bounds and create a list of valid intervals
    valid_intervals = []
    for s, e in areas:
        start = max(s, 0)
        end = min(e, l)
        if end > start:
            valid_intervals.append((start, end))

    if not valid_intervals:
        return l

    # Sort the intervals by start
    valid_intervals.sort(key=lambda x: x[0])

    # Merge overlapping intervals and sum their lengths
    total_cleared = 0
    cur_start, cur_end = valid_intervals[0]

    for s, e in valid_intervals[1:]:
        if s > cur_end:
            total_cleared += cur_end - cur_start
            cur_start, cur_end = s, e
        else:
            cur_end = max(cur_end, e)

    total_cleared += cur_end - cur_start

    return max(0, l - total_cleared)

