def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    if m == 0:
        return 1
    total = sum(a)
    if m > total:
        return 0
    dp = [0] * (m + 1)
    dp[0] = 1
    for limit in a:
        prefix = 0
        new_dp = [0] * (m + 1)
        for j in range(m + 1):
            prefix = (prefix + dp[j]) % MOD
            if j - limit - 1 >= 0:
                prefix = (prefix - dp[j - limit - 1]) % MOD
            new_dp[j] = prefix
        dp = new_dp
    return dp[m] % MOD

def mod_inverse(a, b):
    """
    Calculate the modular multiplicative inverse of `a` modulo `b` using the Extended Euclidean Algorithm.
    Returns the inverse if `a` and `b` are coprime, otherwise returns None.
    """
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, u, v = extended_gcd(y, x % y)
        return (g, v, u - (x // y) * v)

    g, x, _ = extended_gcd(a, b)
    if g != 1:
        return None
    return x % b

def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 1:
        return 0
    # increasing subsequence length ending at each index
    inc = [1] * n
    for i in range(n):
        hi = heights[i]
        max_len = 1
        for j in range(i):
            if heights[j] < hi and inc[j] + 1 > max_len:
                max_len = inc[j] + 1
        inc[i] = max_len
    # decreasing subsequence length starting at each index
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        hi = heights[i]
        max_len = 1
        for j in range(i + 1, n):
            if heights[j] < hi and dec[j] + 1 > max_len:
                max_len = dec[j] + 1
        dec[i] = max_len
    # longest bitonic subsequence length
    best = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1
        if bitonic_len > best:
            best = bitonic_len
    # minimal removals
    return n - best
